import type { RegionId } from "./regions.ts";

/** One face as baked: its region, the lowest height (m) and the grid. */
export type FaceData = {
  readonly id: string;
  readonly region: RegionId;
  readonly floor: number;
  readonly data: string;
};

/** A face as the start card lists it: its region (R21), the RANGE it lies
 * in (a key the start card names: a country's code, or a range across
 * borders), the AREA (the place its ski area is known by) and the PART of
 * that area it is (the area itself where the area is one part). */
export type FaceEntry = {
  readonly id: string;
  readonly region: RegionId;
  readonly range: string;
  readonly area: string;
  readonly part: string;
  /** Where it is, ° to a hundredth: the start card walks a range's areas
   * neighbour to neighbour off it. */
  readonly lat: number;
  readonly lon: number;
};

/** The grid's samples a side and their spacing, m, and a height's step, m. */
export const FACE_GRID = { n: 126, cell: 32, step: 0.5 } as const;

